seen=set(); shapes=[]
for i in range(15):
    for j in range(15):
        if G[i][j]==2 and (i,j) not in seen:
            comp=[]; st=[(i,j)]
            while st:
                a,b=st.pop()
                if not(0<=a<15 and 0<=b<15) or (a,b) in seen or G[a][b]!=2: continue
                seen.add((a,b)); comp.append((a,b))
                for d in ((1,0),(-1,0),(0,1),(0,-1)):
                    st.append((a+d[0],b+d[1]))
            shapes.append(comp)
info=[]
for s in shapes:
    r0=min(r for r,c in s); c0=min(c for r,c in s)
    cells=sorted((r-r0,c-c0) for r,c in s)
    # orientation: stem position relative to bar
    info.append((r0,c0,cells))
for x in info: print(x)

